+package com.pathland.demo;
+
+import com.pathland.render.html.HtmlRenderer;
+import com.pathland.state.redis.RedisStateStore;
+import com.pathland.view.Environment;
+import com.pathland.view.View;
+import com.pathland.view.emit.Emitter;
+import com.pathland.view.emit.Frame;
+import com.pathland.view.emit.FrameOpcodeSink;
+import com.pathland.view.emit.RenderResult;
+import com.pathland.view.signal.EffectRef;
+import com.pathland.view.signal.Signal;
+import com.pathland.view.signal.Signals;
+import com.pathland.view.signal.WritableSignal;
+import com.pathland.view.state.StateStore;
+import com.pathland.view.transport.Event;
+import com.pathland.view.transport.FrameCodec;
+import io.quarkus.websockets.next.WebSocketConnection;
+import jakarta.annotation.PostConstruct;
+import jakarta.annotation.PreDestroy;
+import jakarta.enterprise.context.ApplicationScoped;
+
+import java.util.Map;
+import java.util.Set;
+import java.util.concurrent.CompletableFuture;
+import java.util.concurrent.ConcurrentHashMap;
+import java.util.concurrent.ExecutorService;
+import java.util.concurrent.Executors;
+
+/**
+ * The Pathland application actor: owns the retained view tree, its reactive signals,
+ * the fine-grained emitter, the HTML renderer (SSR state), and the connected WebSocket
+ * clients.
+ *
+ * <p>All signal reads/writes and emission happen on a single actor thread, matching the
+ * single-threaded app-actor model (signals are not thread-safe by contract). Inbound
+ * events are dispatched onto the actor; outbound deltas are broadcast from it.
+ *
+ * <p>State is persisted through {@link StateStore} — Redis when reachable, with an
+ * in-memory fallback — so the identical view code runs unchanged on a server, a desktop
+ * app, a browser, or an embedded device by swapping the store.
+ */
+@ApplicationScoped
+public class CounterApp {
+
+    private static final int MAX_EVENT_BATCH = 1 << 16;
+
+    private final ExecutorService actor = Executors.newSingleThreadExecutor(r -> {
+        Thread t = new Thread(r, "pathland-actor");
+        t.setDaemon(true);
+        return t;
+    });
+
+    // --- reactive state (the application's state, owned here) ---
+    private final WritableSignal<Integer> count = Signals.signal("count", 0);
+    private final WritableSignal<String> name = Signals.signal("name", "");
+    private final Signal<String> countLabel = Signals.computed("countLabel", () -> "Count: " + count.get());
+    private final Signal<String> nameLabel = Signals.computed("nameLabel", () -> "Name: " + name.get());
+
+    // --- retained tree + SSR state ---
+    private final HtmlRenderer html = new HtmlRenderer();
+    private final Set<WebSocketConnection> clients = ConcurrentHashMap.newKeySet();
+    private final CompletableFuture<Void> ready = new CompletableFuture<>();
+
+    /**
+     * The opcode sink the emitter writes into. Every completed frame is applied to the
+     * HTML renderer (keeping SSR state live for page reloads) and broadcast to the
+     * connected clients as a self-contained binary delta.
+     */
+    private final FrameOpcodeSink sink = new FrameOpcodeSink() {
+        @Override
+        public void endFrame() {
+            super.endFrame();
+            Frame frame = frame();
+            if (!frame.opcodes().isEmpty()) {
+                html.applyFrame(frame);
+                if (rootId != 0) {
+                    renderedHtml = html.render(rootId);
+                }
+                broadcast(frame);
+            }
+        }
+    };
+
+    private final Emitter emitter = new Emitter(sink);
+
+    private Map<Integer, Runnable> tapActions = Map.of();
+    private int rootId;
+    private volatile String renderedHtml = "";
+    private StateStore<Integer> store;
+    private EffectRef persistEffect;
+
+    @PostConstruct
+    void init() {
+        actor.execute(() -> {
+            try {
+                initialize();
+                ready.complete(null);
+            } catch (Throwable t) {
+                ready.completeExceptionally(t);
+            }
+        });
+    }
+
+    private void initialize() {
+        store = createStore();
+        store.load("counter", Integer.class).ifPresent(count::set);
+
+        RenderResult result = emitter.mount(rootView(), Environment.DEFAULT);
+        tapActions = result.tapActions();
+        rootId = result.rootId();
+        renderedHtml = html.render(rootId);
+
+        // Persist the counter whenever it changes (cross-platform state abstraction).
+        persistEffect = Signals.effect(() -> {
+            int value = count.get();
+            try {
+                store.save("counter", value);
+            } catch (RuntimeException e) {
+                log("persist failed for counter=" + value + ": " + e.getMessage());
+            }
+        });
+    }
+
+    /** The demo view — the exact same DSL a desktop or Spring Boot app would use. */
+    private View rootView() {
+        return View.vstack(
+                View.hstack(
+                        View.text(countLabel),
+                        View.button("Increment", () -> count.update(v -> v + 1))
+                ).padding(16),
+                View.textField("Your name", name),
+                View.text(nameLabel),
+                View.text("Pathland · Quarkus · 16-byte opcode deltas")
+                        .color(com.pathland.view.Color.rgb(0x88, 0x88, 0x88))
+        ).padding(24);
+    }
+
+    private StateStore<Integer> createStore() {
+        try {
+            StateStore<Integer> redis = new RedisStateStore.Provider().store(Integer.class);
+            redis.load("counter", Integer.class); // probe connectivity
+            log("state store: redis");
+            return redis;
+        } catch (RuntimeException e) {
+            log("state store: in-memory (Redis unavailable: " + e.getMessage() + ")");
+            return new com.pathland.view.state.InMemoryStateStore<>();
+        }
+    }
+
+    // ------------------------------------------------------------------
+    // SSR
+    // ------------------------------------------------------------------
+
+    /** The current SSR HTML (with the client script injected). Blocking until init. */
+    public String renderHtml() {
+        ready.join();
+        return renderedHtml.replace("</body>", "<script src=\"/app.js\" defer></script></body>");
+    }
+
+    // ------------------------------------------------------------------
+    // WebSocket plumbing
+    // ------------------------------------------------------------------
+
+    public void register(WebSocketConnection connection) {
+        clients.add(connection);
+    }
+
+    public void unregister(WebSocketConnection connection) {
+        clients.remove(connection);
+    }
+
+    /** Dispatch a binary EVENT batch from a client onto the actor thread. */
+    public void dispatch(byte[] message) {
+        if (message.length > MAX_EVENT_BATCH) {
+            return;
+        }
+        actor.execute(() -> handleEvents(message));
+    }
+
+    private void handleEvents(byte[] message) {
+        try {
+            for (Event event : FrameCodec.decodeEvents(message)) {
+                if (event.isPointerUp()) {
+                    Runnable action = tapActions.get(event.target());
+                    if (action != null) {
+                        action.run();
+                    }
+                } else if (event.isTextChanged()) {
+                    name.set(event.text());
+                }
+            }
+        } catch (RuntimeException e) {
+            log("dropping event batch: " + e.getMessage());
+        }
+    }
+
+    /** Broadcast a delta frame to every connected client (call on the actor thread). */
+    private void broadcast(Frame frame) {
+        if (clients.isEmpty()) {
+            return;
+        }
+        byte[] bytes = FrameCodec.encodeFrame(frame);
+        for (WebSocketConnection client : clients) {
+            client.sendBinary(bytes)
+                    .subscribe()
+                    .with(ignored -> { }, failure -> clients.remove(client));
+        }
+    }
+
+    @PreDestroy
+    void shutdown() {
+        if (persistEffect != null) {
+            persistEffect.destroy();
+        }
+        emitter.destroy();
+        if (store instanceof RedisStateStore<?> redis) {
+            redis.close();
+        }
+        actor.shutdown();
+    }
+
+    private static void log(String message) {
+        System.out.println("[pathland] " + message);
+    }
+}
