///
/// `Frame` is the **transport seam**: both the shared-memory ring (`Host`) and
/// network batch decoders produce frame views, so consumers such as
/// `RenderTree::apply_frame` work identically regardless of origin.
pub struct Frame<'a> {
    slots: &'a [u8],
    arena: &'a [u8],
    start: usize,
    end: usize,
