```java
abstract class ReactiveNode {
    final List<ReactiveNode> consumers = new ArrayList<>();
    final List<ReactiveNode> producers = new ArrayList<>();
    long version;               // bumped when this node's value changes
    boolean dirty = true;       // needs re-evaluation

    abstract void evaluateIfDirty();

    void recordDependency(ReactiveNode producer) {
        ReactiveNode consumer = ReactiveContext.currentConsumer();
        if (consumer == null) return;
        // add edge
        if (consumer.producers.isEmpty() || consumer.producers.get(consumer.producers.size()-1) != producer) {
            // simple append dedup for typical linear chains
            consumer.producers.add(producer);
            producer.consumers.add(consumer);
        }
    }

    void markConsumersDirty() {
        for (ReactiveNode c : consumers) {
            if (!c.dirty) {
                c.dirty = true;
                if (c instanceof Effect eff) {
                    ReactiveContext.schedule(eff);
                }
                c.markConsumersDirty();
            }
        }
    }
}
```

