final class ReactiveContext {
    private static final ThreadLocal<ArrayDeque<ReactiveNode>> CONSUMER_STACK =
        ThreadLocal.withInitial(ArrayDeque::new);

    private ReactiveContext() {}

    static ReactiveNode current() {
        return CONSUMER_STACK.get().peek();
    }

    static void push(ReactiveNode node) {
        ArrayDeque<ReactiveNode> stack = CONSUMER_STACK.get();
        if (stack.contains(node)) {
            throw new IllegalStateException("Circular signal dependency detected for " + node.describe());
        }
        stack.push(node);
    }

    static void pop() {
        CONSUMER_STACK.get().pop();
    }
}
