final class Scheduler {
    static final ArrayDeque<Effect> QUEUE = new ArrayDeque<>();  // single-threaded
    static boolean flushing = false;

    static void schedule(Effect effect) {
        if (!effect.scheduled) {
            effect.scheduled = true;
            QUEUE.add(effect);
        }
        if (!flushing) flush();
    }

    static void flush() {
        if (flushing) return;
        flushing = true;
        try {
            while (!QUEUE.isEmpty()) {
                Effect e = QUEUE.poll();
                e.scheduled = false;
                e.runIfScheduled();
            }
        } finally {
            flushing = false;
