package com.pathland.view.emit;

public final class Emitter {
    private final OpcodeSink sink;
    private int nextId = 1;
    private int rootId = 0;
    private final Map<Integer, Runnable> tapActions = new LinkedHashMap<>();
    private final List<EffectRef> bindings = new ArrayList<>();
    private boolean mounted = false;

    public Emitter(OpcodeSink sink) { this.sink = sink; }

    public RenderResult mount(View root, Environment env) {
        if (mounted) throw new IllegalStateException("already mounted");
        mounted = true;
        PathlandNode tree = root.render(env);
        nextId = 1;
        assignIds(tree);
        tapActions.clear();
        collectTaps(tree);
        sink.beginFrame();
        emitNode(tree);
        sink.endFrame();
        registerBindings(tree);
        this.rootId = tree.id;
        return new RenderResult(tree.id, Map.copyOf(tapActions));
    }

    private void assignIds(PathlandNode node) {
        node.id = nextId++;
        for (PathlandNode child : node.children) assignIds(child);
    }

    private void collectTaps(PathlandNode node) {
        for (Runnable action : node.tapActions) tapActions.put(node.id, action);
        for (PathlandNode c : node.children) collectTaps(c);
    }

    private void emitNode(PathlandNode node) {
        sink.createNode(node.id, node.component);
        String text = node.text;
        if (text != null && !text.isEmpty()) sink.setText(node.id, text);
        for (var e : node.properties.entrySet()) {
            int vt = ValueTypes.forProperty(e.getKey());
            Object v = e.getValue();
            if (vt == ValueTypes.STRING) {
                sink.setProperty(node.id, e.getKey(), vt, (String) v);
            } else {
                sink.setProperty(node.id, e.getKey(), vt, v);
            }
        }
        for (PathlandNode child : node.children) {
            emitNode(child);
            sink.insertChild(node.id, child.id, -1 /* APPEND */);
        }
    }

    private void registerBindings(PathlandNode node) {
        if (node.textBinding != null) {
            bindings.add(Signals.effect(() -> {
                String value = node.textBinding.get();
                if (!Objects.equals(value, node.text)) {
                    node.text = value;
                    sink.beginFrame();
                    sink.setText(node.id, value);
                    sink.endFrame();
                }
            }));
        }
        for (var e : node.propertyBindings.entrySet()) {
            int prop = e.getKey();
            Signal<?> signal = e.getValue();
            bindings.add(Signals.effect(() -> {
                Object value = ReactiveValue.from(prop, signal);
                if (!Objects.equals(value, node.properties.get(prop))) {
                    node.properties.put(prop, value);
                    int vt = ValueTypes.forProperty(prop);
                    sink.beginFrame();
                    sink.setProperty(node.id, prop, vt, value);
                    sink.endFrame();
                }
            }));
        }
        for (PathlandNode child : node.children) registerBindings(child);
    }
}
