package com.pathland.view.emit;

import com.pathland.view.Color;
import com.pathland.view.signal.Signal;

/**
 * Converts a reactive signal's value into the typed property value stored on a
 * {@link PathlandNode}. Booleans become raw {@code 1}/{@code 0}; other values pass
 * through (the property's wire value type drives the final encoding).
 */
public final class ReactiveValues {

    private ReactiveValues() {}

    /** Read the signal and normalize its value for storage as a node property. */
    public static Object from(int property, Signal<?> signal) {
        Object value = signal.get();
        if (value instanceof Boolean b) {
            return b ? 1 : 0;
        }
        if (value instanceof Color) {
            return value;
        }
        if (value instanceof Float || value instanceof Integer) {
            return value;
        }
        if (value instanceof String) {
            return value;
        }
        throw new IllegalArgumentException(
                "Unsupported reactive property value " + value + " for property 0x"
                        + Integer.toHexString(property));
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.Signal;

/**
 * A text leaf. Content is static or bound to a reactive {@link Signal<String>}; a
 * bound text re-emits only this node's {@code SET_TEXT} when the signal changes.
 */
public final class Text implements View {

    private final String text;
    private final Signal<String> binding;

    private Text(String text, Signal<String> binding) {
        this.text = text;
        this.binding = binding;
    }

    /** Static text. */
    public static Text of(String text) {
        return new Text(text, null);
    }

    /** Reactive text (the current value is read at render time). */
    public static Text of(Signal<String> binding) {
        return new Text(null, binding);
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.TEXT);
        if (binding != null) {
            node.textBinding = binding;
            node.text = binding.get();
        } else {
            node.text = text;
        }
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/** An image leaf (a native element; the renderer resolves the visual). */
public final class Image implements View {

    public Image() {}

    @Override
    public PathlandNode render(Environment env) {
        return new PathlandNode(Components.IMAGE);
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/**
 * An sRGB color packed as {@code 0xAARRGGBB} (the protocol's literal color encoding,
 * D65 white point). Renderers resolve the exact visual appearance.
 *
 * <p>{@code Color} doubles as a leaf view: placing it in a stack draws a solid-color
 * fill (an {@code IMAGE} node with {@code BACKGROUND_COLOR}).
 */
public record Color(int argb) implements View {

    public static final Color CLEAR = new Color(0x00000000);
    public static final Color BLACK = new Color(0xFF000000);
    public static final Color WHITE = new Color(0xFFFFFFFF);
    public static final Color RED = new Color(0xFFFF0000);
    public static final Color BLUE = new Color(0xFF2196F3);

    /** A fully opaque sRGB color. */
    public static Color rgb(int r, int g, int b) {
        return new Color(0xFF000000 | (r << 16) | (g << 8) | b);
    }

    /** An sRGB color with explicit alpha ({@code 0..255}). */
    public static Color argb(int a, int r, int g, int b) {
        return new Color((a << 24) | (r << 16) | (g << 8) | b);
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.IMAGE);
        node.properties.put(Properties.BACKGROUND_COLOR, this);
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/** A rectangle shape (a filled native element). */
public final class Rectangle implements View {

    public Rectangle() {}

    @Override
    public PathlandNode render(Environment env) {
        return new PathlandNode(Components.IMAGE);
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/** Flexible space that expands along a stack's main axis. */
public final class Spacer implements View {

