package com.pathland.demo;

import jakarta.inject.Inject;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;

/** Server-side rendering entry point: the initial HTML with {@code data-pathland-id}. */
@Path("/")
public class IndexResource {

    @Inject
    CounterApp app;

    @GET
    @Produces(MediaType.TEXT_HTML)
    public String index() {
        return app.renderHtml();
    }
}

package com.pathland.demo;

import io.quarkus.websockets.next.OnBinaryMessage;
import io.quarkus.websockets.next.OnClose;
import io.quarkus.websockets.next.OnOpen;
import io.quarkus.websockets.next.WebSocket;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.inject.Inject;

import java.nio.ByteBuffer;

/**
 * The live-updates WebSocket endpoint. Clients hydrate the SSR HTML (nothing is sent on
 * connect); the server broadcasts self-contained 16-byte opcode deltas, and the client
 * sends binary {@code EVENT} batches (pointer up / text changed) that are dispatched
 * into the app's reactive state.
 */
@WebSocket(path = "/ws")
public class PathlandSocket {

    @Inject
    WebSocketConnection connection;

    @Inject
    CounterApp app;

    @OnOpen
    void open() {
        app.register(connection);
    }

    @OnClose
    void close() {
        app.unregister(connection);
    }

    @OnBinaryMessage
    void onBinary(ByteBuffer message) {
        byte[] bytes = new byte[message.remaining()];
        message.get(bytes);
        app.dispatch(bytes);
    }
}

