import io.quarkus.arc.Arc;
import io.quarkus.websockets.next.OnBinaryMessage;
import io.quarkus.websockets.next.OnClose;
import io.quarkus.websockets.next.OnOpen;
import io.quarkus.websockets.next.WebSocket;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.inject.Inject;

/**
 * The live-updates WebSocket endpoint. Clients hydrate the SSR HTML (nothing is sent on
 * connect); the server broadcasts self-contained 16-byte opcode deltas, and the client
 * sends binary {@code EVENT} batches (pointer up / text changed) that are dispatched
 * into the app's reactive state.
 */
@WebSocket(path = "/ws")
public class PathlandSocket {

    @Inject
    WebSocketConnection connection;

    @Inject
    CounterApp app;

    @OnOpen
    void open() {
        // Resolve the concrete connection while the session context is active, so the
        // app can send to it later from the actor thread (the CDI proxy is
        // session-scoped and would fail off-thread).
        WebSocketConnection resolved =
                Arc.container().instance(WebSocketConnection.class).get();
        app.register(resolved);
    }

    @OnClose
    void close() {
        WebSocketConnection resolved =
                Arc.container().instance(WebSocketConnection.class).get();
        app.unregister(resolved);
    }

    @OnBinaryMessage
    void onBinary(byte[] message) {
        app.dispatch(message);
    }
}

