        this.rootId = result.rootId();

        // Persist the session's state on change (cross-platform, multi-tenant keying).
        effects.add(Signals.effect(() -> {
            try {
                countStore.save(key("count"), count.get());
            } catch (RuntimeException e) {
                log("persist count failed: " + e.getMessage());
            }
        }));
        effects.add(Signals.effect(() -> {
            try {
                nameStore.save(key("name"), name.get());
            } catch (RuntimeException e) {
                log("persist name failed: " + e.getMessage());
            }
        }));
    }

    private String key(String base) {
        return base + ":" + sessionId;
    }

    /** Wire the live connection AFTER mount (the initial frame was already SSR'd). */
    void connect(WebSocketConnection connection) {
        this.connection = connection;
    }

    /** Send a delta frame to this session's single client (no broadcast). */
    private void send(Frame frame) {
        WebSocketConnection conn = connection;
        if (conn == null) {
            return;
        }
        byte[] bytes = FrameCodec.encodeFrame(frame);
        try {
            conn.sendBinary(bytes)
                    .subscribe()
                    .with(ignored -> { }, failure -> connection = null);
        } catch (RuntimeException e) {
            connection = null;
        }
    }

    /** Dispatch a binary EVENT batch (called on the app-actor thread). */
    void dispatch(byte[] message) {
        try {
            for (Event event : FrameCodec.decodeEvents(message)) {
                if (event.isPointerUp()) {
                    Runnable action = tapActions.get(event.target());
                    if (action != null) {
                        action.run();
                    }
                } else if (event.isTextChanged()) {
                    name.set(event.text());
                }
            }
        } catch (RuntimeException e) {
            log("dropping event batch: " + e.getMessage());
        }
    }

    /** The session's current SSR HTML (with the client script injected). */
    String renderHtml() {
        return html.render(rootId)
                .replace("</body>", "<script src=\"/app.js\" defer></script></body>");
    }

    /** Tear down: stop effects, unsubscribe the emitter, drop the connection. */
    void close() {
        for (EffectRef effect : effects) {
            effect.destroy();
        }
        emitter.destroy();
        connection = null;
    }

    /** The demo view — the exact same DSL a desktop or Spring Boot app would use. */
    private View rootView() {
        return View.vstack(
                View.hstack(
                        View.text(countLabel),
                        View.button("Increment", () -> count.update(v -> v + 1))
                ).padding(16),
                View.textField("Your name", name),
                View.text(nameLabel),
                View.text("Pathland · Quarkus · per-session · 16-byte deltas")
                        .color(Color.rgb(0x88, 0x88, 0x88))
        ).padding(24);
    }

    private static void log(String message) {
        System.out.println("[pathland] " + message);
    }
}

package com.pathland.demo;

import com.pathland.state.redis.RedisStateStore;
import com.pathland.view.state.StateStore;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import jakarta.enterprise.context.ApplicationScoped;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * The application registry. Sessions are <strong>1:1</strong> — each WebSocket connection
 * owns a {@link SessionApp} with its own reactive state; deltas flow only to that client
 * (never broadcast). The registry routes inbound events and tears sessions down.
 *
 * <p>All session work is serialized on a single actor thread (signals are single-threaded
 * by contract). Per-session SSR runs on the request thread against thread-safe
 * {@link StateStore}s (a throwaway {@link SessionApp}).
 *
 * <p>State is persisted through {@link StateStore} keyed by session id — Redis when
 * reachable, with an in-memory fallback — so the identical view code runs unchanged on a
 * server, a desktop app, a browser, or an embedded device by swapping the store.
 */
@ApplicationScoped
public class PathlandApp {

    private static final int MAX_EVENT_BATCH = 1 << 16;

    private final ExecutorService actor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "pathland-actor");
        t.setDaemon(true);
        return t;
    });

    private final Map<String, SessionApp> sessions = new ConcurrentHashMap<>();
    private StateStore<Integer> countStore;
    private StateStore<String> nameStore;

    @PostConstruct
    void init() {
        countStore = createStore("count");
        nameStore = createStore("name");
    }

    // ------------------------------------------------------------------
    // SSR
    // ------------------------------------------------------------------

    /** Render the SSR HTML for a session's persisted state (request thread). */
    public String renderHtml(String sessionId) {
        SessionApp app = new SessionApp(sessionId, countStore, nameStore);
        try {
            return app.renderHtml();
        } finally {
            app.close();
        }
    }

    // ------------------------------------------------------------------
    // WebSocket (1:1 sessions)
    // ------------------------------------------------------------------

    /** Create (or replace) the session for a connection; wires deltas to it only. */
    public void open(String sessionId, WebSocketConnection connection) {
        actor.execute(() -> {
            SessionApp previous = sessions.remove(sessionId);
            if (previous != null) {
                previous.close();
            }
            SessionApp app = new SessionApp(sessionId, countStore, nameStore);
            app.connect(connection);
            sessions.put(sessionId, app);
        });
    }

    /** Route an inbound event batch to the owning session. */
    public void dispatch(String sessionId, byte[] message) {
        if (message.length > MAX_EVENT_BATCH) {
            return;
        }
        actor.execute(() -> {
            SessionApp app = sessions.get(sessionId);
            if (app != null) {
                app.dispatch(message);
            }
        });
    }

    /** Close and remove a session. */
    public void close(String sessionId) {
        actor.execute(() -> {
            SessionApp app = sessions.remove(sessionId);
            if (app != null) {
                app.close();
            }
        });
    }

    @PreDestroy
    void shutdown() {
        for (SessionApp app : sessions.values()) {
            app.close();
        }
        sessions.clear();
        actor.shutdown();
    }

    private <T> StateStore<T> createStore(String label) {
        try {
            StateStore<T> redis = new RedisStateStore.Provider().store(null);
            redis.load("probe", null); // probe connectivity (untyped)
            log("state store: redis (" + label + ")");
            return redis;
        } catch (RuntimeException e) {
            log("state store: in-memory (" + label + ", Redis unavailable: " + e.getMessage() + ")");
            return new com.pathland.view.state.InMemoryStateStore<>();
        }
    }

    private static void log(String message) {
        System.out.println("[pathland] " + message);
    }
}

