import com.pathland.view.transport.Event;
import com.pathland.view.transport.FrameCodec;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.WebSocket;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.CompletableFuture;

/** WS test client: sends the session cookie, emits one event, prints decoded deltas. */
public class WsClient {
    public static void main(String[] args) throws Exception {
        String session = args[0];
        String action = args.length > 1 ? args[1] : "click"; // click | text
        HttpClient client = HttpClient.newHttpClient();
        List<String> received = new ArrayList<>();

        WebSocket ws = client.newWebSocketBuilder()
                .header("Cookie", "session=" + session)
                .buildAsync(URI.create("ws://localhost:8080/ws"), new WebSocket.Listener() {
                    @Override
                    public void onOpen(WebSocket webSocket) {
                        byte[] batch = action.equals("click")
                                ? FrameCodec.encodeEvents(List.of(Event.pointerUp(4, 0, 0)))
                                : FrameCodec.encodeEvents(List.of(Event.textChanged(5, "Alice")));
                        webSocket.sendBinary(ByteBuffer.wrap(batch), true);
                    }

                    @Override
                    public CompletionStage<?> onBinary(WebSocket webSocket, ByteBuffer data, boolean last) {
                        byte[] bytes = new byte[data.remaining()];
                        data.get(bytes);
                        try {
                            for (Event e : FrameCodec.decodeEvents(bytes)) {
                                received.add("EVENT target=" + e.target() + " cmd=" + e.command());
                            }
                        } catch (Exception ex) {
                            // it's a guest->host frame (SET_TEXT), decode manually
                            received.add(decodeSetText(bytes));
                        }
                        webSocket.request(1);
                        return CompletableFuture.completedFuture(null);
                    }
                }).join();

        Thread.sleep(500);
        ws.sendClose(WebSocket.NORMAL_CLOSURE, "done").join();
        Thread.sleep(100);
        System.out.println(String.join("\n", received));
        System.exit(0);
    }

    private static String decodeSetText(byte[] bytes) {
        var v = ByteBuffer.wrap(bytes).order(java.nio.ByteOrder.LITTLE_ENDIAN);
        int count = v.getInt(12);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            int pos = 16 + i * 16;
            int cat = bytes[pos] & 0xFF;
            int cmd = bytes[pos + 1] & 0xFF;
            int node = v.getInt(pos + 4);
            if (cat == 2 && cmd == 3) { // SET_TEXT
                int off = v.getInt(pos + 8);
                int stringsLen = v.getInt(16 + count * 16);
                byte[] strings = new byte[stringsLen];
                System.arraycopy(bytes, 16 + count * 16 + 4, strings, 0, stringsLen);
                int len = ByteBuffer.wrap(strings).order(java.nio.ByteOrder.LITTLE_ENDIAN).getInt(off);
                sb.append("SET_TEXT node=").append(node).append(" text=")
                        .append(new String(strings, off + 4, off + 4 + len));
            }
        }
        return sb.toString();
    }
}

